import{_ as t,o,c as i,ae as a}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"支付宝账单导入教程","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/03-alipay-bill-import-guide.md","filePath":"v1/zh/guide/03-alipay-bill-import-guide.md"}'),r={name:"v1/zh/guide/03-alipay-bill-import-guide.md"};function e(n,l,u,d,h,s){return o(),i("div",null,[...l[0]||(l[0]=[a('<h1 id="支付宝账单导入教程" tabindex="-1">支付宝账单导入教程 <a class="header-anchor" href="#支付宝账单导入教程" aria-label="Permalink to &quot;支付宝账单导入教程&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>本教程将指导您如何从支付宝导出账单，并导入到考拉记账 App 中。</p><hr><h2 id="📱-第一步-在支付宝中导出账单" tabindex="-1">📱 第一步：在支付宝中导出账单 <a class="header-anchor" href="#📱-第一步-在支付宝中导出账单" aria-label="Permalink to &quot;📱 第一步：在支付宝中导出账单&quot;">​</a></h2><h3 id="步骤-1-打开支付宝账单页面" tabindex="-1">步骤 1：打开支付宝账单页面 <a class="header-anchor" href="#步骤-1-打开支付宝账单页面" aria-label="Permalink to &quot;步骤 1：打开支付宝账单页面&quot;">​</a></h3><ol><li>打开支付宝 App</li><li>点击底部导航栏的 <strong>&quot;我的&quot;</strong> 标签</li><li>点击 <strong>&quot;账单&quot;</strong> 进入账单页面</li></ol><blockquote><p>📝 <strong>注意</strong>：不同版本的支付宝，入口可能略有不同。如果找不到，可以尝试在支付宝搜索框搜索&quot;账单&quot;。</p></blockquote><h3 id="步骤-2-导出账单" tabindex="-1">步骤 2：导出账单 <a class="header-anchor" href="#步骤-2-导出账单" aria-label="Permalink to &quot;步骤 2：导出账单&quot;">​</a></h3><ol><li>在账单页面，点击右上角的 <strong>&quot;...&quot;</strong> 按钮</li><li>选择 <strong>&quot;开具交流流水证明&quot;</strong> 或 <strong>&quot;账单导出&quot;</strong></li><li>选择**“用户个人对帐”<strong>，并点击</strong>“申请”</li></ol><h3 id="步骤-3-选择交易流水范围" tabindex="-1">步骤 3：选择交易流水范围 <a class="header-anchor" href="#步骤-3-选择交易流水范围" aria-label="Permalink to &quot;步骤 3：选择交易流水范围&quot;">​</a></h3><ol><li>选择交易类型，“全部交易”/“收入”/“支出”</li><li>选择要导出的时间范围（如：最近一个月、最近三个月等）</li><li>选择接收方式，“支付宝”/“邮箱”</li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建议一次导出不超过 3 个月的数据，避免文件过大</li><li>如果需要导出更长时间的数据，可以分多次导出</li><li>导出后，如果选择接收方式为“邮箱”，支付宝会通过邮件发送账单文件</li><li>您需要先设置支付宝的邮箱地址（如果未设置）</li><li>或者选择&quot;保存到文件&quot;（如果支持）</li></ul></blockquote><h3 id="步骤-4-保存文件到设备" tabindex="-1">步骤 4：保存文件到设备 <a class="header-anchor" href="#步骤-4-保存文件到设备" aria-label="Permalink to &quot;步骤 4：保存文件到设备&quot;">​</a></h3><ol><li><p>如果选择邮件发送：</p><ul><li>打开邮箱，找到支付宝发送的邮件</li><li>下载附件（CSV 文件）</li><li>保存到设备本地（可以通过文件管理器访问）</li></ul></li><li><p>如果选择&quot;保存到文件&quot;：</p><ul><li>文件会保存到设备的下载文件夹</li><li>记住文件保存的位置</li></ul></li></ol><blockquote><p>📝 <strong>文件位置提示</strong>：</p><ul><li>iOS：文件通常保存在&quot;文件&quot;App 的&quot;下载&quot;文件夹</li><li>Android：文件通常保存在&quot;下载&quot;文件夹或&quot;支付宝&quot;文件夹</li></ul></blockquote><hr><h2 id="📱-第二步-在考拉记账中导入" tabindex="-1">📱 第二步：在考拉记账中导入 <a class="header-anchor" href="#📱-第二步-在考拉记账中导入" aria-label="Permalink to &quot;📱 第二步：在考拉记账中导入&quot;">​</a></h2><h3 id="步骤-1-进入导入页面" tabindex="-1">步骤 1：进入导入页面 <a class="header-anchor" href="#步骤-1-进入导入页面" aria-label="Permalink to &quot;步骤 1：进入导入页面&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面中找到 <strong>&quot;账单导入&quot;</strong> 选项</li><li>点击进入账单导入页面</li></ol><h3 id="步骤-2-选择导入来源" tabindex="-1">步骤 2：选择导入来源 <a class="header-anchor" href="#步骤-2-选择导入来源" aria-label="Permalink to &quot;步骤 2：选择导入来源&quot;">​</a></h3><ol><li>点击 <strong>&quot;导入来源&quot;</strong> 选项</li><li>在弹出的列表中选择 <strong>&quot;支付宝&quot;</strong></li><li>确认选择</li></ol><blockquote><p>⚠️ <strong>重要</strong>：必须选择&quot;支付宝&quot;，否则系统无法正确解析文件格式。</p></blockquote><h3 id="步骤-3-选择文件" tabindex="-1">步骤 3：选择文件 <a class="header-anchor" href="#步骤-3-选择文件" aria-label="Permalink to &quot;步骤 3：选择文件&quot;">​</a></h3><ol><li>点击 <strong>&quot;文件路径&quot;</strong> 选项</li><li>在文件选择器中找到并选择支付宝导出的账单文件</li><li>确认文件已选择（会显示文件名）</li></ol><blockquote><p>📝 <strong>文件格式</strong>：</p><ul><li>支持 CSV 格式（<code>.csv</code>）</li><li>文件名通常包含&quot;支付宝&quot;或&quot;Alipay&quot;字样</li></ul></blockquote><h3 id="步骤-4-关联账本" tabindex="-1">步骤 4：关联账本 <a class="header-anchor" href="#步骤-4-关联账本" aria-label="Permalink to &quot;步骤 4：关联账本&quot;">​</a></h3><ol><li>点击 <strong>&quot;关联账本&quot;</strong> 选项</li><li>选择要将账单导入到哪个账本</li><li>确认账本选择</li></ol><blockquote><p>💡 <strong>提示</strong>：如果只有一个账本，系统会自动关联默认账本。</p></blockquote><h3 id="步骤-5-解析文件" tabindex="-1">步骤 5：解析文件 <a class="header-anchor" href="#步骤-5-解析文件" aria-label="Permalink to &quot;步骤 5：解析文件&quot;">​</a></h3><ol><li>点击右上角的 <strong>&quot;解析&quot;</strong> 按钮</li><li>等待系统解析文件（可能需要几秒钟）</li><li>解析成功后，会自动跳转到预览页面</li></ol><blockquote><p>⚠️ <strong>如果解析失败</strong>：</p><ul><li>检查文件格式是否正确</li><li>检查是否选择了&quot;支付宝&quot;作为导入来源</li><li>检查文件是否损坏</li><li>尝试重新从支付宝导出文件</li></ul></blockquote><h3 id="步骤-6-预览和编辑" tabindex="-1">步骤 6：预览和编辑 <a class="header-anchor" href="#步骤-6-预览和编辑" aria-label="Permalink to &quot;步骤 6：预览和编辑&quot;">​</a></h3><p>解析成功后，您可以在预览页面中：</p><ul><li><strong>查看所有账单记录</strong>：按日期分组显示</li><li><strong>编辑单条记录</strong>：点击记录可以修改： <ul><li>分类（支出/收入分类）</li><li>金额</li><li>时间</li><li>账户</li><li>标签</li><li>备注</li></ul></li><li><strong>删除无效记录</strong>：长按记录可以删除</li><li><strong>批量操作</strong>：可以选择跳过无效记录</li></ul><blockquote><p>📝 <strong>建议</strong>：</p><ul><li>在导入前，先预览数据，确保数据正确</li><li>检查分类是否正确匹配</li><li>检查金额是否正确</li><li>如有需要，可以手动调整分类和账户</li></ul></blockquote><h3 id="步骤-7-导入数据" tabindex="-1">步骤 7：导入数据 <a class="header-anchor" href="#步骤-7-导入数据" aria-label="Permalink to &quot;步骤 7：导入数据&quot;">​</a></h3><ol><li>在预览页面确认数据无误后</li><li>点击 <strong>&quot;导入&quot;</strong> 按钮</li><li>等待导入完成（可能需要几秒钟）</li><li>导入成功后，会显示导入结果</li></ol><blockquote><p>✅ <strong>导入成功</strong>：所有有效记录已导入到账本中，您可以在账单列表中查看。</p></blockquote><hr><h2 id="📋-支付宝账单文件格式说明" tabindex="-1">📋 支付宝账单文件格式说明 <a class="header-anchor" href="#📋-支付宝账单文件格式说明" aria-label="Permalink to &quot;📋 支付宝账单文件格式说明&quot;">​</a></h2><h3 id="csv-格式-标准格式" tabindex="-1">CSV 格式（标准格式） <a class="header-anchor" href="#csv-格式-标准格式" aria-label="Permalink to &quot;CSV 格式（标准格式）&quot;">​</a></h3><p>支付宝导出的 CSV 文件通常包含以下列：</p><table tabindex="0"><thead><tr><th>列名</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>交易时间</td><td>交易创建时间</td><td>2024-01-01 12:00:00</td></tr><tr><td>交易分类</td><td>账单的收支名称</td><td>餐饮美食/日用百货</td></tr><tr><td>交易对方</td><td>交易对方信息</td><td>张三 / 商户名称</td></tr><tr><td>对方账号</td><td>对方的支付宝账号</td><td><a href="mailto:xxx@163.com" target="_blank" rel="noreferrer">xxx@163.com</a></td></tr><tr><td>商品说明</td><td>商品描述</td><td>午餐 / 购物等</td></tr><tr><td>收/支</td><td>收入或支出</td><td>收入 / 支出</td></tr><tr><td>金额</td><td>交易金额</td><td>100.00</td></tr><tr><td>收/付款方式</td><td>何种方式的账户</td><td>余额宝</td></tr><tr><td>交易状态</td><td>交易状态</td><td>交易成功 / 已退款</td></tr><tr><td>交易订单号</td><td>交易单号</td><td>2024010112345678901234567890</td></tr><tr><td>商家订单号</td><td>商家订单号</td><td>1234567890</td></tr><tr><td>备注</td><td>备注信息</td><td>备注内容</td></tr></tbody></table><blockquote><p>📝 <strong>注意</strong>：不同版本的支付宝，列名可能略有不同，但主要内容相同。</p></blockquote><hr><h2 id="⚠️-注意事项" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><h3 id="_1-文件格式要求" tabindex="-1">1. 文件格式要求 <a class="header-anchor" href="#_1-文件格式要求" aria-label="Permalink to &quot;1. 文件格式要求&quot;">​</a></h3><ul><li><strong>文件编码</strong>：建议使用 UTF-8 编码（支付宝导出通常为 UTF-8 或 GBK）</li><li><strong>文件格式</strong>：仅支持 CSV 格式（<code>.csv</code>）</li><li><strong>文件大小</strong>：建议单个文件不超过 10MB</li></ul><h3 id="_2-数据映射" tabindex="-1">2. 数据映射 <a class="header-anchor" href="#_2-数据映射" aria-label="Permalink to &quot;2. 数据映射&quot;">​</a></h3><p>系统会自动将支付宝账单字段映射到考拉记账字段：</p><ul><li>交易时间（CSV 第1列 / row[0]）→ 本地账单时间 （仅取日期， yyyy-MM-dd ）</li><li>交易分类（第2列 / row[1]）→ 本地账单父子分类 （父子同名）</li><li>交易对方（第3列 / row[2]）→ 本地账单备注 （追加一行“交易对方:xxx”，表头名随源文件）</li><li>对方账号（第4列 / row[3]）→ 本地账单备注 （追加一行“对方账号:xxx”，表头名随源文件）</li><li>商品说明（第5列 / row[4]）→ 本地账单备注 （追加一行“商品说明:xxx”，表头名随源文件）</li><li>收/支（第6列 / row[5]）→ 本地账单类型（收入/支出）</li><li>金额（第7列 / row[6]）→ 本地账单金额</li><li>收/付款方式（第8列 / row[7]）→ 本地账户名称 （按名称查找账户，不存在则创建后写入）</li><li>交易状态（第9列 / row[8]）→ 本地账单备注（追加一行“交易状态:xxx”，表头名随源文件）</li><li>交易订单号（第10列 / row[9]）→ 本地账单备注（追加一行“交易订单号:xxx”，表头名随源文件）</li><li>商家订单号（第11列 / row[10]）→ 本地账单备注 （追加一行“商家订单号:xxx”，表头名随源文件）</li><li>备注（第12列 / row[11]）→ 本地账单备注（作为原始备注；若为 / 或空则忽略，再叠加上述追加项）</li></ul><h3 id="_3-分类匹配" tabindex="-1">3. 分类匹配 <a class="header-anchor" href="#_3-分类匹配" aria-label="Permalink to &quot;3. 分类匹配&quot;">​</a></h3><ul><li>系统会尝试自动匹配分类，但可能不完全准确</li><li>建议在预览页面检查分类是否正确</li><li>如有需要，可以手动调整分类</li></ul><h3 id="_4-账户匹配" tabindex="-1">4. 账户匹配 <a class="header-anchor" href="#_4-账户匹配" aria-label="Permalink to &quot;4. 账户匹配&quot;">​</a></h3><ul><li>系统会尝试根据&quot;交易来源地&quot;或其他信息匹配账户</li><li>如果账户不存在，系统会自动创建</li><li>建议在导入前先创建好常用账户</li></ul><h3 id="_5-重复数据处理" tabindex="-1">5. 重复数据处理 <a class="header-anchor" href="#_5-重复数据处理" aria-label="Permalink to &quot;5. 重复数据处理&quot;">​</a></h3><ul><li>如果导入的记录与现有记录重复（基于交易号），系统会自动跳过</li><li>建议在导入前先检查是否有重复数据</li></ul><h3 id="_6-退款处理" tabindex="-1">6. 退款处理 <a class="header-anchor" href="#_6-退款处理" aria-label="Permalink to &quot;6. 退款处理&quot;">​</a></h3><ul><li>如果账单包含退款记录，系统会尝试识别并处理</li><li>退款记录通常标记为&quot;已退款&quot;或&quot;退款成功&quot;</li><li>建议在预览页面检查退款记录是否正确</li></ul><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-找不到-导出账单-选项" tabindex="-1">Q1：找不到&quot;导出账单&quot;选项？ <a class="header-anchor" href="#q1-找不到-导出账单-选项" aria-label="Permalink to &quot;Q1：找不到&quot;导出账单&quot;选项？&quot;">​</a></h3><p><strong>A：</strong> 可能的原因：</p><ol><li>支付宝版本较旧，不支持导出功能</li><li>入口位置不同，可以尝试： <ul><li>在账单页面点击右上角的&quot;...&quot;按钮</li><li>在&quot;我的&quot;页面查找&quot;账单&quot;选项</li><li>在支付宝搜索框搜索&quot;账单导出&quot;</li></ul></li></ol><h3 id="q2-导出后收不到邮件" tabindex="-1">Q2：导出后收不到邮件？ <a class="header-anchor" href="#q2-导出后收不到邮件" aria-label="Permalink to &quot;Q2：导出后收不到邮件？&quot;">​</a></h3><p><strong>A：</strong> 请检查：</p><ol><li>支付宝是否绑定了邮箱地址</li><li>邮箱地址是否正确</li><li>邮件是否被放入垃圾箱</li><li>可以尝试选择&quot;保存到文件&quot;方式</li></ol><h3 id="q3-解析失败怎么办" tabindex="-1">Q3：解析失败怎么办？ <a class="header-anchor" href="#q3-解析失败怎么办" aria-label="Permalink to &quot;Q3：解析失败怎么办？&quot;">​</a></h3><p><strong>A：</strong> 请检查：</p><ol><li>文件格式是否正确（CSV）</li><li>是否选择了&quot;支付宝&quot;作为导入来源</li><li>文件是否损坏</li><li>文件编码是否正确（建议使用 UTF-8 或 GBK）</li></ol><h3 id="q4-导入后分类不正确" tabindex="-1">Q4：导入后分类不正确？ <a class="header-anchor" href="#q4-导入后分类不正确" aria-label="Permalink to &quot;Q4：导入后分类不正确？&quot;">​</a></h3><p><strong>A：</strong> 这是正常现象，因为：</p><ol><li>支付宝的分类和考拉记账的分类可能不完全匹配</li><li>系统会尝试自动匹配，但可能不完全准确</li><li>建议在预览页面手动调整分类，或导入后批量修改</li></ol><h3 id="q5-可以导入图片吗" tabindex="-1">Q5：可以导入图片吗？ <a class="header-anchor" href="#q5-可以导入图片吗" aria-label="Permalink to &quot;Q5：可以导入图片吗？&quot;">​</a></h3><p><strong>A：</strong> 目前不支持。支付宝账单不包含图片信息，导入后也无法添加图片。</p><h3 id="q6-支持导入多长时间的数据" tabindex="-1">Q6：支持导入多长时间的数据？ <a class="header-anchor" href="#q6-支持导入多长时间的数据" aria-label="Permalink to &quot;Q6：支持导入多长时间的数据？&quot;">​</a></h3><p><strong>A：</strong> 理论上没有限制，但建议：</p><ol><li>单次导入不超过 3 个月的数据</li><li>如果数据量很大，可以分多次导入</li><li>导入过程中请保持 App 在前台运行</li></ol><h3 id="q7-为什么只支持-csv-格式" tabindex="-1">Q7：为什么只支持 CSV 格式？ <a class="header-anchor" href="#q7-为什么只支持-csv-格式" aria-label="Permalink to &quot;Q7：为什么只支持 CSV 格式？&quot;">​</a></h3><p><strong>A：</strong> 支付宝目前只支持导出 CSV 格式的账单文件。如果将来支持 Excel 格式，我们会及时更新。</p><hr><h2 id="⚠️-注意事项-1" tabindex="-1">⚠️ 注意事项 <a class="header-anchor" href="#⚠️-注意事项-1" aria-label="Permalink to &quot;⚠️ 注意事项&quot;">​</a></h2><h3 id="_1-文件格式要求-1" tabindex="-1">1. 文件格式要求 <a class="header-anchor" href="#_1-文件格式要求-1" aria-label="Permalink to &quot;1. 文件格式要求&quot;">​</a></h3><ul><li><strong>文件编码</strong>：建议使用 UTF-8 编码（微信导出通常为 UTF-8）</li><li><strong>文件格式</strong>：仅支持 CSV格式</li><li><strong>文件大小</strong>：建议单个文件不超过 10MB</li></ul><h3 id="_3-分类匹配-1" tabindex="-1">3. 分类匹配 <a class="header-anchor" href="#_3-分类匹配-1" aria-label="Permalink to &quot;3. 分类匹配&quot;">​</a></h3><ul><li>系统会尝试自动匹配分类，但可能不完全准确</li><li>建议在预览页面检查分类是否正确</li><li>如有需要，可以手动调整分类</li></ul><h3 id="_4-账户匹配-1" tabindex="-1">4. 账户匹配 <a class="header-anchor" href="#_4-账户匹配-1" aria-label="Permalink to &quot;4. 账户匹配&quot;">​</a></h3><ul><li>系统会尝试根据&quot;支付方式&quot;匹配账户</li><li>如果账户不存在，系统会自动创建</li><li>建议在导入前先创建好常用账户</li></ul><h3 id="_5-重复数据处理-1" tabindex="-1">5. 重复数据处理 <a class="header-anchor" href="#_5-重复数据处理-1" aria-label="Permalink to &quot;5. 重复数据处理&quot;">​</a></h3><ul><li>建议在导入前先检查是否有重复数据</li></ul><h3 id="_6-不要手动修改账单" tabindex="-1">6. 不要手动修改账单 <a class="header-anchor" href="#_6-不要手动修改账单" aria-label="Permalink to &quot;6. 不要手动修改账单&quot;">​</a></h3><ul><li>不要手动修改支付宝账单，包括但不限于修改、删除表头名称或者或新增列，这会导致解析账单失败</li></ul><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>定期导入</strong>：建议每月导入一次，保持数据同步</li><li><strong>分类整理</strong>：导入后，建议检查并整理分类，方便后续统计</li><li><strong>账户管理</strong>：导入前先创建好常用账户，避免自动创建不规范的账户名</li><li><strong>数据备份</strong>：导入前建议先备份现有数据，以防万一</li><li><strong>退款处理</strong>：导入后，建议检查退款记录是否正确处理</li></ol><hr><p><strong>最后更新</strong>：2026年5月</p>',97)])])}const b=t(r,[["render",e]]);export{c as __pageData,b as default};
